const sourceMap = new Map(SOIL_LESSON_SOURCES.map(s => [s.id, s]));
const refs = (keys: readonly string[]) => keys.map(key => { const s = sourceMap.get(sid(key)); if (!s) throw new Error("Unknown soil source " + key); return s; });
const block = (text: string, keys: readonly string[], evidence: HistoryBlock["evidence"] = "interpretation"): HistoryBlock => ({ text, evidence, sourceIds: keys.map(sid) });
type Row = readonly [string, string, boolean, string];
const choices = (rows: readonly Row[]): readonly HistoryChoice[] => rows.map(([id, text, correct, feedback]) => ({ id, text, correct, feedback }));
function activity(ch: string, part: number | "checkpoint", kind: HistoryActivity["kind"], title: string, scenario: string, prompt: string, rows: readonly Row[], reasons: readonly Row[], takeaway: string, keys: readonly string[]): HistoryActivity {
  return { id: "soil-" + ch + (part === "checkpoint" ? "-checkpoint" : "-activity-" + part), kind, title, scenario, fictional: true, evaluates: prompt, steps: [{ id: "decision", prompt, choices: choices(rows), reasonPrompt: "Quelle raison soutient votre réponse ?", reasons: choices(reasons), sourceIds: keys.map(sid) }], takeaway };
}
type Draft = { title: string; question: string; objective: string; essential: readonly string[]; example: string; deeper: string; nodes: readonly (readonly [string, string])[]; activity: HistoryActivity; terms: readonly string[]; next: string; keys: readonly string[]; buddyCodes?: readonly string[] };
function lesson(ch: string, part: number, d: Draft): HistoryLesson {
  return { id: lid(ch, part), title: d.title, question: d.question, objective: d.objective, minutes: 4, essential: d.essential.map(t => block(t, d.keys)), example: block(d.example, d.keys, "fiction"), deeper: [block(d.deeper, d.keys)], visual: { kind: "evidence", title: d.question, nodes: d.nodes.map(([label, detail]) => ({ label, detail })), caption: "Schéma de raisonnement : relations qualitatives, sans proportion ni prescription.", sourceIds: d.keys.map(sid) }, activity: d.activity, glossaryIds: d.terms.map(tid), relatedLessonIds: [lid(ch, part === 1 ? 2 : 1)], nextQuestion: d.next, ...(d.buddyCodes ? { buddyCodes: d.buddyCodes } : {}) };
}

const physicalLessons = [
  lesson("physical", 1, { title: "Des grains, des agrégats, des pores", question: "Un sol argileux est-il forcément compact ?", objective: "Distinguer texture et structure dans une coupe de sol.",
    essential: ["La texture décrit les proportions de sable, limon et argile de la fraction minérale fine. La structure décrit leur organisation en agrégats, avec des pores entre et dans ces assemblages. Un agrégat contient plusieurs particules ; il n’est pas un gros grain de sable. Deux sols de texture semblable peuvent donc présenter des structures différentes.", "Les pores accueillent de l’eau ou de l’air. Leur taille, leur continuité et leur occupation changent le fonctionnement du sol. Le tassement réorganise et comprime cet espace : il peut gêner l’enracinement et les échanges. Une texture ne suffit pas à déclarer un sol bon ou mauvais. On examine le profil, ses horizons et les obstacles réellement présents."],
    example: "Dans deux coupes fictives de même texture, l’une montre des agrégats et des passages continus ; l’autre une couche comprimée. La différence porte d’abord sur la structure.",
    deeper: "La granulométrie est une mesure des classes de taille ; la structure se décrit aussi sur le terrain. Une terre émiettée pour l’analyse ne conserve pas l’organisation du profil intact. Une forte proportion d’argile ne signifie donc pas automatiquement absence d’air, et ajouter une matière organique ne transforme pas des particules argileuses en sable. L’observation des racines et des pores complète le résultat de laboratoire, sans imposer une proportion idéale commune à tous les sols.",
    nodes: [["Texture", "Proportions des particules minérales"], ["Structure", "Assemblages et organisation"], ["Porosité", "Espaces et connexions"]],
    activity: activity("physical", 1, "diagram", "Lire la coupe", "Deux sols fictifs ont les mêmes proportions de particules mais des assemblages et pores différents.", "Quelle propriété diffère directement ?", [["a", "La structure.", true, "L’organisation change alors que les proportions minérales restent identiques."], ["b", "Nécessairement la texture.", false, "Le dossier conserve précisément les mêmes proportions."], ["c", "Nécessairement la concentration de chaque nutriment.", false, "Une coupe ne fournit pas ces dosages."]], [["a", "Les assemblages et les pores ne sont pas les proportions de sable, limon et argile.", true, "La distinction explique deux fonctionnements possibles à texture semblable."], ["b", "Tout sol argileux est dépourvu de pores.", false, "Les sols argileux possèdent des pores dont l’organisation varie."]], "Texture et structure répondent à deux questions différentes.", ["physical", "compaction"]), terms: ["texture", "structure", "aggregate", "pore"], next: "Toute l’eau présente est-elle accessible aux racines ?", keys: ["physical", "compaction"] }),
  lesson("physical", 2, { title: "Eau stockée, eau accessible", question: "Un sol plus humide fournit-il toujours davantage d’eau ?", objective: "Distinguer infiltration, drainage et réserve accessible.",
    essential: ["L’infiltration est l’entrée de l’eau dans le sol ; le drainage correspond à son déplacement et à son évacuation sous l’effet des gradients, notamment de la gravité. Une partie demeure retenue dans les pores. Toute cette eau n’est pas également accessible : une fraction est fortement liée aux surfaces, et les racines n’explorent pas forcément tout le profil.", "La réserve utile dépend notamment de la texture, de la structure, de l’épaisseur explorée et des éléments grossiers. Un horizon compact ou un enracinement limité change l’accès réel. À l’autre extrême, des pores durablement remplis d’eau peuvent freiner le renouvellement de l’air. Humide ne signifie donc ni bien aéré ni nutrition assurée."],
    example: "Le dossier fictif décrit un horizon humide sous une couche qui limite les racines. Cette eau existe, mais sa présence ne prouve pas qu’elle soit entièrement accessible à la plante.",
    deeper: "Une réserve est exprimée pour une profondeur et un volume de sol définis. On ne compare pas un pourcentage d’eau mesuré en surface à une réserve de tout le profil. La vitesse d’infiltration ne décrit pas seule la capacité de stockage : des passages préférentiels peuvent conduire rapidement l’eau en profondeur. Les observations de circulation, de rétention et de racines se complètent. Aucun chiffre du parcours ne prescrit une irrigation ou un seuil universel de sécheresse.",
    nodes: [["Entrer", "Infiltration"], ["Rester ou circuler", "Rétention et drainage"], ["Être accessible", "État de l’eau et racines présentes"]],
    activity: activity("physical", 2, "choice", "La réserve hors d’atteinte", "Un profil fictif possède un horizon humide, mais aucune racine n’y est observée et une couche dense limite la pénétration.", "Que peut-on conclure ?", [["a", "Toute l’eau du profil alimente déjà la plante.", false, "La quantité présente ne prouve pas l’accès racinaire."], ["b", "L’eau est présente ; son accès effectif reste à examiner.", true, "La conclusion conserve la distinction entre stockage et utilisation."], ["c", "La couche dense prouve une absence totale d’eau.", false, "Le dossier mentionne au contraire un horizon humide."]], [["a", "La réserve théorique et le volume réellement exploré ne coïncident pas toujours.", true, "La profondeur des racines compte dans l’interprétation."], ["b", "La seule couleur sombre mesure la réserve accessible.", false, "La couleur ne remplace pas les mesures et l’examen du profil."]], "Associer eau, pores et profondeur explorée.", ["physical", "compaction"]), terms: ["infiltration", "drainage", "available-water", "compaction"], next: "Pourquoi les racines ont-elles aussi besoin d’oxygène ?", keys: ["physical", "compaction"] }),
];

const rhizosphereLessons = [
  lesson("rhizosphere", 1, { title: "La racine échange avec son milieu", question: "La racine est-elle seulement une paille qui aspire ?", objective: "Relier absorption, respiration et rhizosphère.",
    essential: ["Les racines ancrent la plante et participent à l’absorption de l’eau et des éléments nutritifs. Leurs cellules respirent : elles utilisent de l’oxygène pour une production d’énergie nécessaire à leur fonctionnement. Une eau présente autour des racines ne suffit donc pas si les échanges gazeux sont fortement limités.", "La rhizosphère est la zone de sol influencée par les racines. Celles-ci y prélèvent des ressources et libèrent des composés, les exsudats. Ces échanges modifient les conditions locales et l’activité d’organismes voisins. L’influence varie dans l’espace et dans le temps ; la rhizosphère n’est ni une couche uniforme de taille fixe ni une communauté automatiquement bénéfique."],
    example: "Sur le schéma fictif, des flèches entrent et sortent de la racine. Elles représentent des échanges qualitatifs, pas une vitesse mesurée ni une recette de nutrition.",
    deeper: "Le carbone fixé par les parties vertes peut alimenter les racines et certains échanges avec les organismes du sol. La respiration racinaire ne doit pas être confondue avec la photosynthèse, ni avec la seule respiration microbienne. La disponibilité d’un ion près de la racine dépend de sa concentration, de son déplacement et de réactions locales. Les travaux forestiers du WSL éclairent ces mécanismes ; leurs images et résultats ne mesurent pas directement un lot de chanvre.",
    nodes: [["Racine", "Respiration et absorption"], ["Exsudats", "Composés libérés dans le voisinage"], ["Rhizosphère", "Zone d’interactions changeantes"]],
    activity: activity("rhizosphere", 1, "diagram", "Compléter les échanges", "Un schéma fictif montre une racine et son voisinage immédiat.", "Quel ensemble décrit correctement les échanges ?", [["a", "Uniquement de l’eau entrant dans un tube inerte.", false, "La racine est vivante, respire et échange aussi des composés."], ["b", "Une photosynthèse obligatoire dans toutes les racines du sol.", false, "La fonction étudiée ici est la respiration de cellules racinaires."], ["c", "Absorption, respiration et libération d’exsudats.", true, "Ces processus participent aux interactions avec le milieu."]], [["a", "L’activité racinaire transforme localement le milieu tout en dépendant de lui.", true, "L’influence est réciproque, sans bénéfice universel garanti."], ["b", "Tout composé libéré nourrit exclusivement des organismes utiles.", false, "L’identité et les effets des organismes doivent être étudiés."]], "Une racine vivante participe aux échanges du sol.", ["rhizosphere", "physical"]), terms: ["root-respiration", "rhizosphere", "exudate"], next: "Une feuille pâle indique-t-elle forcément un manque dans le sol ?", keys: ["rhizosphere", "physical"] }),
  lesson("rhizosphere", 2, { title: "Un symptôme, plusieurs mécanismes", question: "Faut-il ajouter un élément dès qu’une feuille jaunit ?", objective: "Distinguer manque, indisponibilité et absorption perturbée.",
    essential: ["Un jaunissement est une observation, pas le nom d’une carence. Un élément peut manquer dans certaines formes disponibles ; il peut aussi être présent mais peu accessible. L’état hydrique, l’aération, la chimie du milieu et le fonctionnement des racines peuvent limiter son absorption. Une atteinte racinaire ou une autre cause peut produire des symptômes ressemblants.", "On compare donc plusieurs hypothèses : quantité insuffisante, disponibilité limitée, difficulté d’absorption ou problème distinct. La répartition des symptômes, l’historique et des analyses adaptées apportent des indices. Une photographie seule ne prescrit pas d’engrais. Ajouter un produit sans comprendre le mécanisme peut laisser la cause intacte et créer un excès."],
    example: "Une plante fictive pâlit dans un milieu humide, avec des racines altérées. Le dossier ne fournit aucune analyse nutritive : plusieurs explications restent ouvertes.",
    deeper: "Le stock total du sol, la fraction extraite au laboratoire et la quantité dans un tissu végétal répondent à des questions différentes. Même une analyse de feuille doit être interprétée selon l’organe, le stade, le prélèvement et les références adaptées. Une couleur peut être commune à plusieurs troubles. Le lien vers le parcours Santé permet d’examiner les hypothèses pathologiques sans transformer cette leçon en clé diagnostique certaine ou en programme de fertilisation.",
    nodes: [["Stock", "L’élément existe-t-il, sous quelles formes ?"], ["Accès", "Peut-il rejoindre une racine fonctionnelle ?"], ["Observation", "Quels indices départagent les causes ?"]],
    activity: activity("rhizosphere", 2, "dossier", "La feuille pâle", "Cas fictif : feuilles pâles, milieu humide, racines altérées ; aucune analyse du sol ou des tissus.", "Quelle conclusion est défendable ?", [["a", "Une carence précise est confirmée par la couleur.", false, "La couleur ne distingue pas les différentes causes possibles."], ["b", "Diagnostic non confirmé ; examiner racines, milieu, historique et analyses pertinentes.", true, "Cette réponse conserve le différentiel et indique les informations utiles."], ["c", "Un stock total élevé exclurait tout problème d’absorption.", false, "Présence totale et absorption réelle ne sont pas équivalentes."]], [["a", "Des mécanismes différents peuvent produire une apparence semblable.", true, "Il faut des observations discriminantes avant d’agir."], ["b", "Le nom commercial du végétal permet de choisir une correction universelle.", false, "Le nom ne décrit ni ce sol ni l’état de ces racines."]], "Chercher le mécanisme avant de proposer une réponse.", ["physical", "nutrition", "rhizosphere"]), terms: ["availability", "uptake", "differential"], next: "Quels organismes participent aux transformations autour des racines ?", keys: ["physical", "nutrition", "rhizosphere"] }),
];

const lifeLessons = [
  lesson("life", 1, { title: "Un réseau, pas une équipe uniforme", question: "Tous les habitants du sol rendent-ils le même service ?", objective: "Associer groupes biologiques et fonctions possibles sans généraliser.",
    essential: ["Les bactéries et les champignons comprennent des organismes aux fonctions diverses : décomposition, transformations nutritives, associations avec les racines, mais aussi maladies dans certains cas. Les protozoaires, catégorie pratique regroupant divers organismes unicellulaires, peuvent consommer des microbes. Les nématodes ont plusieurs régimes alimentaires. La faune, dont arthropodes et vers de terre, participe à la fragmentation, aux déplacements de matière et aux réseaux alimentaires.", "Ces groupes interagissent. La diversité décrit une communauté ; elle ne prouve pas que toutes les fonctions soient réalisées au même niveau. Voir un organisme, lui attribuer une fonction et démontrer un bénéfice dans un contexte sont trois étapes différentes. Un sol vivant n’est pas une garantie commerciale de rendement ou d’absence de pathogènes."],
    example: "Dans une observation fictive, un nématode est visible mais non identifié. Le joueur conserve son régime alimentaire inconnu au lieu de le classer automatiquement nuisible ou auxiliaire.",
    deeper: "Un réseau trophique représente qui utilise quelles ressources. Les organismes ne se limitent pas à une chaîne linéaire ; plusieurs voies se croisent et certains rôles changent selon les espèces et les conditions. Les catégories de taille ne remplacent pas l’identification. Des indicateurs de diversité, d’abondance et d’activité peuvent se compléter, mais ne mesurent pas exactement la même chose. Le nombre d’organismes annoncé pour une autre étude ne devient pas une mesure de notre parcelle.",
    nodes: [["Décomposer", "Transformer des matières organiques"], ["Consommer", "Réseaux de proies et de ressources"], ["Transformer le milieu", "Agrégats, galeries, échanges"]],
    activity: activity("life", 1, "matching", "Présence et fonction", "Un nématode non identifié apparaît dans un dossier fictif ; aucune alimentation n’a été observée.", "Quelle attribution est justifiée ?", [["a", "Régime et effet encore indéterminés.", true, "Le groupe comprend des régimes différents."], ["b", "Ravageur confirmé parce que c’est un nématode.", false, "Tous les nématodes ne se nourrissent pas des racines."], ["c", "Bénéfice garanti parce qu’il appartient à la vie du sol.", false, "Présence biologique ne signifie pas bénéfice démontré."]], [["a", "Une appartenance générale ne suffit pas à établir une fonction précise.", true, "Identification et interaction complètent l’observation."], ["b", "Tous les organismes microscopiques jouent le même rôle.", false, "Le réseau réunit des fonctions variées."]], "Ne pas confondre vivant, fonctionnel et bénéfique.", ["biology", "living"]), terms: ["food-web", "protozoa", "soil-fauna", "diversity"], next: "Une mycorhize présente garantit-elle un gain ?", keys: ["biology", "living"] }),
  lesson("life", 2, { title: "Évaluer les promesses d’inoculants", question: "Introduire un microbe utile donne-t-il toujours un bénéfice ?", objective: "Séparer présence, mécanisme et résultat dans un essai.",
    essential: ["Une mycorhize est une association entre un champignon et des racines. Elle peut contribuer aux échanges de ressources, avec un coût et un résultat dépendant des partenaires et du milieu. Un inoculant apporte des organismes sélectionnés ; son nom ou sa présence après apport ne démontre pas un bénéfice pratique.", "Dans les essais de Lutz et collègues sur 54 champs de maïs suisses, la réponse à une inoculation mycorhizienne varie entre sites. Ce résultat interdit de promettre le même effet partout. Il ne prouve ni que les inoculants fonctionnent toujours, ni qu’ils sont toujours inutiles. Il faut comparer un critère mesuré, un témoin et des conditions pertinentes pour la question posée."],
    example: "Une publicité fictive transforme une colonisation racinaire observée en garantie de récolte. Le joueur demande le résultat comparatif et son contexte avant d’accepter cette promesse.",
    deeper: "La légende de la figure 3 de Lutz distingue implantation du champignon et réponse de croissance : leur relation n’est pas automatique dans ce corpus. Un essai sur maïs ne valide pas un produit pour tous les chanvres. On examine l’identité de l’inoculant, les conditions initiales, les comparateurs et les résultats sans sélectionner seulement les cas favorables. Les informations réglementaires du produit constituent encore une vérification distincte de l’efficacité annoncée.",
    nodes: [["Présence", "Organisme détecté"], ["Fonction", "Interaction ou mécanisme étudié"], ["Bénéfice", "Résultat comparé dans un contexte"]],
    activity: activity("life", 2, "documents", "La promesse du flacon", "Annonce fictive : champignon détecté sur les racines, donc gain garanti sur tout chanvre. Aucun résultat comparatif n’est fourni.", "Quelle réponse est étayée ?", [["a", "La détection prouve la garantie annoncée.", false, "Implantation et bénéfice sont des résultats différents."], ["b", "La détection prouve que le produit est toujours inutile.", false, "L’absence de preuve de gain ici ne prouve pas une absence générale d’effet."], ["c", "Le bénéfice n’est pas établi ; demander essai, comparateur et contexte.", true, "La conclusion respecte le niveau de preuve disponible."]], [["a", "Un mécanisme possible doit être relié à un résultat mesuré dans des conditions pertinentes.", true, "La réponse peut varier selon le système."], ["b", "Le mot mycorhize remplace toutes les données d’essai.", false, "La catégorie ne garantit aucun résultat universel."]], "Une promesse doit être évaluée au niveau où elle est formulée.", ["inoculation", "living", "fertilisers"]), terms: ["mycorrhiza", "inoculant", "comparator"], next: "Que deviennent les matières organiques dans ce réseau ?", keys: ["inoculation", "living", "fertilisers"] }),
];

const organicLessons = [
  lesson("organic", 1, { title: "Suivre les transformations", question: "Une feuille morte devient-elle directement nourriture pour la racine ?", objective: "Reconstituer une branche du cycle sans effacer ses autres voies.",
    essential: ["La décomposition fragmente et transforme les résidus grâce à des processus biologiques et physicochimiques. Une partie du carbone rejoint la biomasse d’organismes, une autre retourne à l’atmosphère par respiration ; une autre peut persister dans le sol. La minéralisation transforme des éléments liés à des matières organiques en formes minérales.", "L’immobilisation fait le trajet inverse pour des nutriments : des organismes incorporent des formes minérales dans leur biomasse. Ces processus peuvent coexister. Pour l’azote, la minéralisation peut libérer de l’ammonium ; la nitrification est une transformation distincte vers des formes oxydées. Une partie des éléments peut être absorbée, retenue, déplacée ou perdue. Le cycle n’est pas une livraison immédiate et complète aux racines."],
    example: "Le schéma fictif suit une seule branche : résidu organique, transformations, formes minérales, absorption possible. Les autres flèches rappellent biomasse, respiration et pertes possibles.",
    deeper: "Le rapport carbone/azote renseigne une composition, sans donner à lui seul une vitesse de transformation. La nature des composés, leur accès aux organismes et les conditions du milieu comptent également. L’immobilisation temporaire ne détruit pas l’azote : il change de compartiment. Inversement, la minéralisation ne garantit pas une absorption, car disponibilité et besoins ne coïncident pas nécessairement. Les flèches du parcours représentent des voies possibles, jamais des pourcentages mesurés.",
    nodes: [["Entrées organiques", "Résidus et composés issus du vivant"], ["Transformations", "Biomasse, minéralisation, respiration"], ["Destins", "Absorption, rétention, nouvelles transformations ou pertes"]],
    activity: activity("organic", 1, "order", "Reconstituer une branche du cycle", "Le dossier fictif suit un élément lié à un résidu organique jusqu’à une absorption possible. Il ne représente pas la totalité des flux.", "Quelle suite est cohérente ?", [["a", "Résidu → transformations et minéralisation → forme minérale → absorption possible.", true, "Cette branche distingue les étapes sans garantir le dernier passage."], ["b", "Résidu → absorption complète immédiate de tout son contenu.", false, "Les transformations, immobilisations et autres destins sont oubliés."], ["c", "Forme minérale → immobilisation signifie disparition définitive de l’élément.", false, "L’élément est incorporé à la biomasse, pas détruit."]], [["a", "Un élément change de forme ou de compartiment ; sa présence ne garantit pas son absorption.", true, "Le raisonnement conserve les voies concurrentes."], ["b", "La minéralisation et l’immobilisation sont synonymes.", false, "Elles décrivent des passages opposés pour les nutriments concernés."]], "Un cycle comprend plusieurs voies, pas une promesse d’apport immédiat.", ["nitrogen", "biology"]), terms: ["decomposition", "mineralisation", "immobilisation", "nitrification"], next: "Que recouvre réellement le mot humus ?", keys: ["nitrogen", "biology"] }),
  lesson("organic", 2, { title: "Des matières organiques au pluriel", question: "Le sol possède-t-il un unique stock d’humus permanent ?", objective: "Distinguer diversité des matières, fractions mesurées et persistance.",
    essential: ["Les matières organiques du sol comprennent des résidus, des composés transformés et des produits issus des organismes. Leur fonctionnement n’est pas uniforme. Le mot humus possède plusieurs sens historiques : constituants organiques transformés ou organisation d’horizons de surface. L’humification désigne des transformations, pas la fabrication démontrée d’un seul matériau universel et éternel.", "On peut distinguer des fractions particulaires et des matières associées aux minéraux selon des méthodes précises. Protection dans des agrégats, associations minérales et accessibilité aux organismes influencent la persistance. Une fraction relativement persistante reste susceptible de transformations. Un taux de carbone ne décrit donc pas à lui seul toute la diversité des matières organiques ni leur fonctionnement futur."],
    example: "Deux sols fictifs affichent la même teneur en carbone mais des fractions et des contextes différents. Le joueur refuse d’en déduire une fertilité ou une vitesse de minéralisation identiques.",
    deeper: "L’étude de Cotrufo et collègues combine des données européennes et un fractionnement de sols forestiers et prairiaux. Elle montre l’intérêt de distinguer des compartiments opérationnels ; elle ne fournit pas un modèle universel de chanvre. Le carbone organique mesuré et une estimation de matière organique ne sont pas la même variable. Un facteur de conversion, lorsqu’il est utilisé, reste une convention ou une approximation à documenter, pas une composition identique de toutes les matières.",
    nodes: [["Matières diverses", "Origines et transformations variées"], ["Fractions", "Séparées selon une méthode annoncée"], ["Persistance", "Liée aux interactions et au contexte"]],
    activity: activity("organic", 2, "choice", "Même carbone, même fonctionnement ?", "Deux dossiers fictifs donnent le même carbone organique total mais aucune information identique sur les fractions ou le milieu.", "Quelle conclusion retenir ?", [["a", "Leurs vitesses de minéralisation sont forcément égales.", false, "La teneur seule ne décrit pas l’accessibilité et les conditions."], ["b", "La teneur est comparable ; le fonctionnement complet n’est pas établi.", true, "On conserve la portée de la mesure."], ["c", "Tout le carbone appartient à un humus permanent.", false, "Les matières organiques sont diverses et restent transformables."]], [["a", "Un indicateur global ne distingue pas toutes les formes et leurs interactions.", true, "D’autres informations peuvent être nécessaires."], ["b", "Le mot humus possède partout une définition analytique unique.", false, "Les usages historiques et les méthodes diffèrent."]], "Nommer la variable et sa méthode avant de parler de stock stable.", ["humus", "fractions", "methods"]), terms: ["organic-matter", "humus", "humification", "organic-carbon", "fraction"], next: "Quels éléments participent aux fonctions de la plante ?", keys: ["humus", "fractions", "methods"] }),
];

const nutrientLessons = [
  lesson("nutrients", 1, { title: "Des éléments, plusieurs fonctions", question: "N, P et K suffisent-ils à décrire la nutrition ?", objective: "Associer les éléments majeurs à des fonctions sans leur attribuer un pouvoir exclusif.",
    essential: ["L’azote N entre notamment dans les acides aminés et les protéines. Le phosphore P participe aux acides nucléiques et aux transferts d’énergie. Le potassium K intervient dans des régulations osmotiques et enzymatiques. Ces fonctions traversent plusieurs organes et étapes : aucun élément ne se réduit à une promesse de racines, fleurs ou feuilles.", "Le calcium Ca participe aux parois, membranes et signaux cellulaires ; le magnésium Mg entre dans la chlorophylle et intervient dans des enzymes ; le soufre S entre dans certains acides aminés. Ces éléments sont essentiels. Les besoins quantitatifs diffèrent, mais secondaire ne signifie pas facultatif. Le carbone, l’hydrogène et l’oxygène contribuent aussi à la matière végétale ; les engrais n’en constituent pas l’unique origine."],
    example: "Dans les cartes fictives, Mg est relié à la chlorophylle, et P aux transferts d’énergie. Cette association vérifie une fonction connue, sans diagnostiquer une carence sur photo.",
    deeper: "Un élément assure plusieurs fonctions et une fonction mobilise plusieurs éléments. La respiration, la photosynthèse ou la construction de tissus ne dépendent donc pas d’un seul symbole d’étiquette. Une association élément–fonction est une simplification pédagogique, pas une hiérarchie de produits à ajouter. La quantité requise, la fourniture du milieu et la quantité absorbée restent des informations distinctes. Les exemples généraux du manuel ne constituent pas des besoins chiffrés applicables à tous les chanvres.",
    nodes: [["N et S", "Constituants de molécules organiques"], ["P et Mg", "Énergie, chlorophylle et enzymes"], ["K et Ca", "Régulations, structures et signaux"]],
    activity: activity("nutrients", 1, "matching", "Relier élément et fonction", "L’atelier fictif propose des associations de fonctions générales, sans état de carence ni recommandation.", "Quelle association est correcte ?", [["a", "Mg : constituant de la chlorophylle ; P : transferts d’énergie.", true, "Ce sont deux fonctions documentées, sans exclusivité."], ["b", "K : élément central de la chlorophylle ; Mg : uniquement un matériau de paroi.", false, "Le magnésium entre dans la chlorophylle ; ces rôles ont été intervertis ou réduits."], ["c", "Ca et S : éléments facultatifs dès que NPK sont présents.", false, "Ils sont essentiels malgré une catégorie quantitative distincte."]], [["a", "Les catégories de quantité ne retirent pas le caractère essentiel des éléments.", true, "Un rôle connu ne devient pas une consigne d’apport."], ["b", "Chaque élément sert exclusivement à un organe.", false, "Les fonctions sont partagées entre de nombreux processus."]], "Apprendre une fonction sans inventer un besoin d’apport.", ["nutrition", "physical"]), terms: ["macronutrient", "nitrogen", "phosphorus", "potassium", "calcium", "magnesium", "sulfur"], next: "Petite quantité signifie-t-elle faible importance ?", keys: ["nutrition", "physical"] }),
  lesson("nutrients", 2, { title: "Oligoéléments et formes disponibles", question: "Un élément présent dans le sol est-il déjà absorbé ?", objective: "Séparer quantité totale, disponibilité et absorption.",
    essential: ["Les oligoéléments essentiels comprennent fer, manganèse, zinc, cuivre, bore, molybdène, chlore et nickel. Ils sont requis en petites quantités, avec des rôles enzymatiques, structuraux ou de régulation. Petit besoin ne signifie ni absence de besoin ni innocuité de tout excès. Le fer participe notamment à des transferts d’électrons ; il n’est pas l’atome central de la chlorophylle.", "Le total d’un élément rassemble différentes formes. Une extraction de laboratoire en mesure une fraction définie ; elle ne reproduit pas exactement une racine. La disponibilité dépend du milieu et du temps. L’absorption est le passage effectif dans la plante. Ces trois niveaux empêchent de conclure carence ou suffisance depuis un stock total ou une couleur seuls."],
    example: "Le dossier fictif possède un total de phosphore mais aucune méthode adaptée d’évaluation de sa disponibilité. Le total ne suffit pas à fixer la nutrition de la plante.",
    deeper: "Les racines absorbent surtout des formes minérales pour les éléments étudiés ici, quelle que soit l’origine organique ou minérale du produit initial. L’azote peut notamment être absorbé sous forme de nitrate ou d’ammonium ; les transformations et les pertes changent ce qui reste accessible. Un résultat exprimé comme élément P n’est pas directement le même nombre qu’une expression en équivalent P₂O₅. Toujours conserver unité, forme déclarée et méthode évite de comparer des chiffres qui ne représentent pas la même chose.",
    nodes: [["Total", "Ensemble des formes mesurées"], ["Fraction extraite", "Résultat dépendant d’une méthode"], ["Absorbé", "Quantité entrée dans la plante"]],
    activity: activity("nutrients", 2, "choice", "Le total ne répond pas à tout", "Une analyse fictive donne seulement la quantité totale d’un élément dans le sol.", "Quelle conclusion serait excessive ?", [["a", "Ce total ne détaille pas toutes les formes disponibles.", false, "Cette réserve est justement nécessaire."], ["b", "Une méthode et un contexte complètent l’interprétation.", false, "Ils sont nécessaires pour relier l’analyse à une question agronomique."], ["c", "La plante absorbe nécessairement toute cette quantité.", true, "C’est la conclusion excessive à repérer : total et absorption diffèrent."]], [["a", "La présence d’un élément ne décrit pas son accès ni son transfert effectif.", true, "Le résultat ne franchit pas automatiquement les étapes suivantes."], ["b", "Un oligoélément ne peut jamais devenir excessif.", false, "Un faible besoin ne rend pas toute quantité sans conséquence."]], "Lire ce qui a été mesuré, sans inventer ce qui a été absorbé.", ["nutrition", "methods", "nitrogen"]), terms: ["micronutrient", "total", "extractable", "availability", "uptake"], next: "Que mesurent pH, conductivité et capacité d’échange ?", keys: ["nutrition", "methods", "nitrogen"] }),
];

const measureLessons = [
  lesson("measures", 1, { title: "Le pH a une méthode", question: "Deux pH différents prouvent-ils une évolution du sol ?", objective: "Lire le milieu de mesure avant de comparer des valeurs.",
    essential: ["Le pH décrit l’acidité d’un milieu ; son échelle est logarithmique. Pour un sol, on mesure généralement une suspension préparée selon une méthode définie. Eau, solution saline, rapport sol/liquide et conditions de mesure comptent. Un pH dans l’eau et un pH dans une solution de chlorure de calcium ne sont pas deux répétitions identiques.", "Le pH influence des réactions chimiques et biologiques, dont la disponibilité de certains éléments. Il ne résume pas la fertilité, et aucun pH parfait ne convient à toutes les situations. Un suivi demande des mesures comparables et un contexte : date, profondeur, zone et historique. Un écart entre méthodes ne prouve pas que le sol s’est acidifié."],
    example: "Dans le dossier fictif, un résultat dans l’eau est comparé à un résultat dans une solution saline. Le joueur commence par noter cette différence de méthode, sans appliquer de correction automatique.",
    deeper: "Les écarts courants rapportés entre pH eau et pH salin ne constituent pas une constante applicable à chaque sol. Le pouvoir tampon, lié à plusieurs constituants, explique aussi pourquoi deux sols au même pH ne réagissent pas forcément pareil à une perturbation. La mesure d’acidité et le choix d’une éventuelle action sont deux étapes distinctes. Les repères de l’article ARVALIS sont liés à son contexte de grandes cultures ; le parcours n’en extrait ni cible universelle ni prescription.",
    nodes: [["Variable", "Acidité mesurée"], ["Méthode", "Suspension et conditions"], ["Interprétation", "Contexte et comparaison pertinente"]],
    activity: activity("measures", 1, "documents", "Deux étiquettes de pH", "Deux résultats fictifs concernent des suspensions différentes ; aucun résultat à méthode commune n’est disponible.", "Peut-on calculer une évolution certaine de l’acidité ?", [["a", "Oui, toute différence de chiffres mesure une évolution réelle.", false, "La méthode change aussi et peut expliquer un écart."], ["b", "Non, il faut d’abord examiner la compatibilité des mesures.", true, "La comparaison ne doit pas confondre méthode et évolution."], ["c", "Oui, un décalage universel transforme toutes les méthodes.", false, "Aucune conversion constante valable partout n’est établie ici."]], [["a", "La valeur dépend du milieu de mesure et du contexte de prélèvement.", true, "Une série temporelle exige une base comparable."], ["b", "Le pH suffit à connaître tous les éléments absorbés.", false, "Il n’est pas une analyse complète de nutrition."]], "Toujours conserver le nom de la méthode avec le pH.", ["ph", "methods"]), terms: ["ph", "buffer", "method"], next: "Pourquoi CEC et EC ne veulent-elles pas dire la même chose ?", keys: ["ph", "methods"] }),
  lesson("measures", 2, { title: "CEC et EC : deux mesures distinctes", question: "La capacité d’échange est-elle une quantité de sels dissous ?", objective: "Distinguer charges échangeables et conductivité électrique.",
    essential: ["La CEC, capacité d’échange cationique, décrit une capacité de rétention et d’échange de cations sur des surfaces du sol à des conditions données. Elle dépend notamment de la nature des argiles, des matières organiques et du pH. Une méthode à pH fixé et une mesure effective ne décrivent pas nécessairement la même capacité.", "L’EC, conductivité électrique, renseigne la conduction du courant, liée notamment aux ions dissous et aux conditions de mesure. Un extrait dilué, un extrait de pâte saturée et une mesure apparente au terrain ne s’interprètent pas indifféremment. L’EC ne nomme pas chaque ion ; la CEC ne chiffre pas une salinité. Leurs unités, méthodes et significations doivent rester visibles."],
    example: "Le tableau fictif place la CEC en cmol(+)/kg et l’EC en dS/m dans deux colonnes. Il ne les additionne pas et ne les dessine pas sur une même échelle de qualité.",
    deeper: "Une CEC élevée ne prouve pas que tous les besoins sont couverts : elle ne donne ni la composition complète des cations retenus ni la quantité effectivement absorbée. Une EC plus élevée peut refléter différents mélanges d’ions ; elle ne dit pas que davantage d’azote utile est présent. La température et la préparation de l’extrait comptent pour comparer les conductivités. CEC effective et CEC Metson à pH fixé demandent également leur propre interprétation, sans classement automatique des sols.",
    nodes: [["CEC · cmol(+)/kg", "Capacité d’échange de cations"], ["EC · dS/m", "Conductivité de la mesure définie"], ["Méthodes", "Nécessaires pour comparer"]],
    activity: activity("measures", 2, "matching", "Rendre chaque mesure à sa définition", "Deux cartes fictives sont mélangées : capacité d’échange et conduction dans un extrait.", "Quelle association est correcte ?", [["a", "CEC : conduction ; EC : réserve de tous les éléments.", false, "Les notions sont inversées et la réserve totale n’est mesurée par aucune des deux."], ["b", "CEC et EC : deux unités du même indicateur.", false, "Elles décrivent des propriétés différentes."], ["c", "CEC : échange de cations ; EC : conductivité liée aux ions et aux conditions.", true, "La réponse conserve les définitions et leur portée."]], [["a", "Une capacité de surface et une conduction dans un milieu ne sont pas la même propriété.", true, "Leurs unités et méthodes ne sont pas interchangeables."], ["b", "Plus une mesure est grande, meilleur est forcément le sol.", false, "Une valeur doit être interprétée selon la question et le contexte."]], "CEC n’est pas EC : nom, unité et méthode ensemble.", ["ph", "ec", "methods"]), terms: ["cec", "ec", "cation", "salinity"], next: "Quel objectif distingue un engrais d’un amendement ?", keys: ["ph", "ec", "methods"] }),
];

const inputLessons = [
  lesson("inputs", 1, { title: "Nommer la fonction de l’apport", question: "Engrais et amendement sont-ils deux noms du même objectif ?", objective: "Classer par fonction sans confondre origine et effet.",
    essential: ["Un engrais vise principalement à fournir des éléments nutritifs. Un amendement vise principalement à modifier ou entretenir des propriétés du sol, physiques, chimiques ou biologiques. Certains matériaux peuvent participer aux deux fonctions ; cela n’efface pas la nécessité de préciser l’objectif et la composition. Un support de culture sert de milieu à la plante, ce qui est encore une autre fonction.", "Organique, minéral et naturel ne désignent pas à eux seuls une vitesse, une efficacité ou une sécurité. Un produit organique peut contenir des formes minérales ; un apport minéral peut interagir avec la vie du sol. Le raisonnement commence par la question à résoudre, puis examine le produit exact, sa caractérisation et son cadre d’emploi."],
    example: "Deux fiches fictives annoncent respectivement fourniture d’un élément et modification d’une propriété du sol. Le joueur les classe par fonction principale, sans déduire leur innocuité de leur origine.",
    deeper: "La catégorie générale ne remplace pas l’étiquette, l’analyse ou le statut réglementaire. E-Phy présente les matières fertilisantes, leurs adjuvants et les supports de culture ; ce catalogue ne signifie pas que toute matière naturelle possède une autorisation universelle. Le cours ne tranche pas une mise sur le marché depuis un slogan. Un matériau à double fonction peut nécessiter de considérer à la fois ses apports nutritifs et ses autres effets, y compris les excès possibles.",
    nodes: [["Engrais", "Fourniture nutritive principale"], ["Amendement", "Propriétés du sol visées"], ["Support", "Milieu de développement racinaire"]],
    activity: activity("inputs", 1, "matching", "Fonction avant slogan", "Dans des fiches fictives, A vise la fourniture nutritive, B l’entretien des propriétés du sol et C sert de milieu racinaire.", "Quel classement suit les fonctions annoncées ?", [["a", "A engrais ; B amendement ; C support de culture.", true, "Le classement suit l’objectif principal, avec chevauchements possibles."], ["b", "A amendement ; B support ; C engrais, parce que tout agit sur la plante.", false, "Agir sur la plante ne rend pas les fonctions identiques."], ["c", "Tout est sans risque dès que l’origine est naturelle.", false, "L’origine ne prouve ni innocuité ni statut d’emploi."]], [["a", "La fonction principale se distingue de l’origine et des effets secondaires possibles.", true, "Il faut ensuite examiner la composition et le contexte."], ["b", "Une matière ne peut jamais remplir plusieurs fonctions.", false, "Certains matériaux apportent des nutriments et modifient des propriétés du sol."]], "Classer un objectif n’est pas prescrire un produit.", ["fertilisers", "nutrition", "compost"]), terms: ["fertiliser", "amendment", "growing-medium"], next: "À quel rythme un apport devient-il utilisable ?", keys: ["fertilisers", "nutrition", "compost"] }),
  lesson("inputs", 2, { title: "La disponibilité a une histoire", question: "Une origine organique garantit-elle un effet lent et sans perte ?", objective: "Raisonner formes, transformations et temporalité.",
    essential: ["La forme chimique et les transformations nécessaires influencent la disponibilité d’un élément. Un composé organique peut devoir être transformé ; un élément déjà en solution peut être retenu, absorbé ou entraîné ailleurs. Aucun mot d’origine ne garantit une libération parfaitement synchronisée avec les besoins.", "L’activité biologique, l’humidité, l’aération et les interactions chimiques modifient les trajectoires. Minéralisation, immobilisation, échanges et pertes peuvent se produire en parallèle. Une action proportionnée tient compte des fournitures déjà présentes, de l’historique et des observations. Plus d’apport ne signifie pas toujours plus d’absorption ni meilleur résultat. Le parcours ne déduit aucun dosage ou calendrier de ces mécanismes."],
    example: "Deux produits fictifs d’origine semblable n’ont pas les mêmes formes déclarées. Leur origine commune ne permet pas d’affirmer une vitesse de disponibilité identique.",
    deeper: "L’azote illustre des destins distincts : incorporation biologique, transformations entre formes, transfert avec l’eau ou perte gazeuse selon les conditions. Le nitrate ne se comporte pas comme un cation retenu sur les mêmes sites d’échange. À l’inverse, une partie de l’ammonium peut participer aux échanges cationiques. Ce sont des mécanismes à comprendre, pas des instructions pour conduire une culture. Un bilan sérieux précise son périmètre et garde inconnus les flux qui n’ont pas été mesurés.",
    nodes: [["Forme initiale", "Ce qui est réellement apporté"], ["Transformations", "Milieu et organismes"], ["Résultat", "Absorption, rétention ou pertes possibles"]],
    activity: activity("inputs", 2, "choice", "La libération prétendument garantie", "Une publicité fictive affirme : organique signifie toujours lent, sans excès ni perte.", "Quelle reformulation est rigoureuse ?", [["a", "La formule est vraie pour toutes les matières organiques.", false, "Leur composition et leur transformation sont variables."], ["b", "Il faut examiner les formes, les transformations et le contexte.", true, "L’origine seule ne décrit ni rythme ni destination."], ["c", "Tout produit minéral est immédiatement absorbé en totalité.", false, "Il peut aussi être retenu, transformé ou perdu."]], [["a", "La trajectoire d’un élément dépend de plus que son origine.", true, "La disponibilité n’est pas une garantie inscrite dans un adjectif."], ["b", "L’absorption et la quantité apportée sont toujours identiques.", false, "Les autres destins et fournitures du milieu doivent être distingués."]], "Relier la forme à son devenir, sans promesse universelle.", ["nitrogen", "nutrition", "compost"]), terms: ["loss", "leaching", "supply"], next: "Comment caractériser un compost, un fumier ou une couverture ?", keys: ["nitrogen", "nutrition", "compost"] }),
];

const amendmentLessons = [
  lesson("amendments", 1, { title: "Compost et fumier : lire le matériau", question: "Un matériau sombre est-il nécessairement mûr et adapté ?", objective: "Distinguer origine, maturité, stabilité et conformité.",
    essential: ["Un fumier et un compost ne sont pas des matériaux identiques. Leur composition dépend des matières d’origine, des transformations et du stockage. Le compostage transforme des matières organiques ; il ne garantit pas à lui seul la disparition de tous les contaminants ni une composition nutritive fixe.", "La stabilité décrit une résistance à une décomposition biologique supplémentaire ; la maturité renseigne l’aptitude à un usage à partir de plusieurs critères. Elles ne se déduisent pas de la seule couleur. Sels solubles, éléments nutritifs, contaminants et indésirables demandent leurs propres vérifications. Un matériau peut être intéressant pour une fonction et inadapté à un autre contexte. Naturel n’est pas synonyme de caractérisé ou d’inoffensif."],
    example: "Le dossier fictif montre deux composts aussi sombres. Leurs analyses et leurs matières d’origine diffèrent ; le joueur refuse de les déclarer interchangeables.",
    deeper: "Le bulletin d’Oregon State distingue explicitement maturité et stabilité. Les tests biologiques, chimiques et physiques répondent à des questions différentes ; un indicateur isolé ne garantit pas la qualité globale. Les concentrations peuvent aussi être exprimées sur matière brute ou sèche : l’eau change la comparaison. Les seuils et méthodes réglementaires américains ne sont pas transposés ici. En France, statut, caractérisation et conditions pertinentes doivent être vérifiés pour le matériau et l’usage concernés.",
    nodes: [["Origine", "Matières entrantes et traçabilité"], ["État", "Stabilité, maturité et composition"], ["Adéquation", "Usage, risques et cadre vérifiés"]],
    activity: activity("amendments", 1, "documents", "Le compost sombre", "Le compost fictif est sombre et sent la terre ; aucune caractérisation n’accompagne ces observations.", "Qu’est-ce qui est démontré ?", [["a", "L’absence de tout contaminant.", false, "Ni couleur ni odeur ne constituent cette analyse."], ["b", "Une maturité et une adaptation universelles.", false, "Ces propriétés demandent plusieurs critères et un usage défini."], ["c", "Un aspect observé ; les autres propriétés restent à vérifier.", true, "La conclusion n’excède pas les informations présentes."]], [["a", "Les critères visuels ne mesurent pas toutes les propriétés du matériau.", true, "Une caractérisation adaptée complète la description."], ["b", "Tout compost a une composition constante.", false, "Matières initiales et transformations font varier sa composition."]], "L’apparence n’est pas une fiche d’analyse.", ["compost", "fertilisers"]), terms: ["compost", "manure", "maturity", "stability", "contaminant"], next: "Une couverture morte et une plante vivante ont-elles les mêmes effets ?", keys: ["compost", "fertilisers"] }),
  lesson("amendments", 2, { title: "Paillis et couverts : des fonctions à distinguer", question: "Couvrir le sol suffit-il à connaître son bilan ?", objective: "Relier protection, racines vivantes et transformations sans recette.",
    essential: ["Un paillis est une couverture de surface ; un couvert végétal vivant possède des racines et participe activement aux échanges. Ces dispositifs peuvent protéger la surface et modifier le milieu, mais ils ne sont pas identiques. Une plante vivante utilise aussi de l’eau et des nutriments ; ses résidus suivent ensuite des transformations.", "La nature des matériaux, leur histoire et le contexte conditionnent les effets. Un résidu carboné ne devient pas instantanément azote disponible. Une couverture ne garantit ni absence d’adventices ni absence de contaminants. On précise l’objectif : protection de surface, maintien de racines, devenir des résidus ou autre fonction. Les compromis doivent être documentés au lieu de transformer couvrir en promesse universelle."],
    example: "Dans un projet fictif, une couverture morte protège la surface tandis qu’un couvert vivant entretient des racines actives. Leurs fonctions se recoupent partiellement, mais leur consommation de ressources diffère.",
    deeper: "Les racines d’un couvert peuvent contribuer à la structuration et aux échanges de la rhizosphère. Les organismes transforment les résidus selon leur accès et le milieu. Ces processus peuvent modifier l’équilibre entre immobilisation et minéralisation sans qu’un rapport C/N seul donne une date de disponibilité. Le guide chanvre décrit la couverture et les rotations dans un cadre agricole ; on n’en déduit ici ni espèce à semer, ni recette de paillage, ni calendrier de conduite.",
    nodes: [["Paillis", "Matériau en surface"], ["Couvert vivant", "Racines et échanges actifs"], ["Résidus", "Transformations ultérieures"]],
    activity: activity("amendments", 2, "matching", "Deux couvertures, deux fonctionnements", "Le projet fictif compare une couverture morte et un couvert vivant, sans prescription d’espèce ni de quantité.", "Quelle différence est pertinente ?", [["a", "Le couvert vivant possède des racines actives et utilise des ressources.", true, "La couverture morte ne fonctionne pas comme une plante vivante."], ["b", "Le paillis fixe nécessairement l’azote atmosphérique.", false, "Une couverture matérielle ne démontre pas ce mécanisme biologique."], ["c", "Les deux fournissent toujours immédiatement les mêmes nutriments.", false, "Nature, transformations et prélèvements diffèrent."]], [["a", "Une fonction de protection commune ne rend pas tous les flux identiques.", true, "Le bilan dépend du fonctionnement et du contexte."], ["b", "La présence de matière en surface prouve l’absence de tout risque.", false, "Origine, conditions et effets doivent être examinés."]], "Distinguer protection de surface et fonctionnement biologique.", ["hemp", "rhizosphere", "nitrogen", "compost"]), terms: ["mulch", "cover-crop", "residue"], next: "Comment comparer les résultats d’un laboratoire sans les surinterpréter ?", keys: ["hemp", "rhizosphere", "nitrogen", "compost"] }),
];

const analysisLessons = [
  lesson("analysis", 1, { title: "Comparer ce qui est comparable", question: "Le plus grand nombre indique-t-il le meilleur sol ?", objective: "Séparer comparaisons valides et résultats obtenus par méthodes différentes.",
    essential: ["Un résultat d’analyse appartient à un échantillon, une date, une profondeur et une méthode. L’unité et la base d’expression comptent autant que le nombre. Un élément total n’est pas une fraction extraite ; une concentration sur terre sèche n’est pas un stock par hectare. Pour un stock, d’autres données seraient nécessaires.", "Les deux analyses pédagogiques A et B sont entièrement fictives. Le carbone organique et l’azote total sont déterminés par combustion sur la même base ; leur rapport est calculable. En revanche, pH, EC, phosphore extractible et CEC utilisent des méthodes différentes. Le tableau permet d’identifier cette incompatibilité, pas de classer directement salinité, acidité, réserve de phosphore ou qualité globale."],
    example: "Données inventées : A contient 18 g C/kg et 1,5 g N/kg ; B contient 24 et 2,0 sur terre fine sèche. Les deux rapports C/N valent 12. Ce calcul ne mesure pas l’azote disponible.",
    deeper: "Les échantillons fictifs sont des composites de deux zones distinctes, à la même date et sur le même horizon. Ils ne forment donc pas une série avant/après. A utilise notamment pH eau et P Olsen, B pH CaCl₂ et P Mehlich 3 ; leurs nombres ne s’ordonnent pas comme deux répétitions de la même mesure. Une différence de concentration en carbone ne prouve pas un stockage supplémentaire par unité de surface, faute de données de volume et de masse du sol correspondantes.",
    nodes: [["Comparable", "Carbone et azote, même méthode et base"], ["Calculable", "C/N avec unités compatibles"], ["Non directement comparable", "pH, EC, P et CEC : méthodes différentes"]],
    activity: activity("analysis", 1, "documents", "Les analyses fictives A et B", "Toutes les valeurs sont inventées. Même date, horizon et base sèche : A C=18 g/kg, N=1,5 g/kg ; B C=24 g/kg, N=2,0 g/kg. Les méthodes de pH, EC, P extractible et CEC diffèrent entre A et B.", "Quelle comparaison est justifiée ?", [["a", "B a davantage de C et de N par kg ; les deux C/N valent 12, sans mesure de N disponible.", true, "Les méthodes et unités de ces deux variables sont communes ; le rapport reste un indicateur de composition."], ["b", "Le plus grand résultat P prouve directement la plus grande fourniture à la plante.", false, "Olsen et Mehlich 3 ne sont pas deux mesures interchangeables ; extraction et absorption diffèrent."], ["c", "La plus grande EC prouve que B est plus salin avec une précision connue.", false, "Les extraits ne sont pas comparables directement, même si l’unité est la même."]], [["a", "Une comparaison numérique exige même variable, méthode compatible et base d’expression.", true, "L’égalité des unités seule ne suffit pas."], ["b", "Un C/N égal rend tous les sols identiques.", false, "De nombreuses propriétés ne sont pas contenues dans ce rapport."]], "Comparer les concentrations autorisées par les méthodes, garder les autres questions ouvertes.", ["methods", "ph", "ec", "nitrogen"]), terms: ["sample", "unit", "cn", "extractable"], next: "Quelle information manque pour interpréter une situation de nutrition ?", keys: ["methods", "ph", "ec", "nitrogen"] }),
  lesson("analysis", 2, { title: "Du bulletin au dossier", question: "Une analyse isolée suffit-elle pour choisir une action ?", objective: "Choisir les informations manquantes qui changent réellement l’interprétation.",
    essential: ["Un prélèvement doit correspondre à la question et au périmètre étudiés. Réunir des zones très différentes peut masquer leur contraste ; sélectionner uniquement un endroit atypique ne décrit pas toute une parcelle. L’identité de la zone, l’horizon, la date et les conditions sont donc conservés avec le résultat. Le laboratoire compétent précise la méthode adaptée.", "L’historique des apports et cultures, l’état des racines, l’humidité et le projet complètent le bulletin. Un suivi répété avec des méthodes compatibles aide à observer une évolution. Il ne prouve pas automatiquement quelle action l’a causée. L’objectif est un dossier interprétable, avec inconnues explicites, plutôt qu’un chiffre transformé immédiatement en ordonnance."],
    example: "Dans le dossier fictif A/B, l’historique des apports et l’état des racines sont absents. Le joueur les demande avant d’expliquer une difficulté de nutrition.",
    deeper: "Une moyenne de composite peut être pertinente pour une zone définie tout en masquant ses variations internes. Le plan d’échantillonnage et la précision analytique sont deux sources distinctes d’incertitude. Pour un suivi, changer de zone, de profondeur ou d’extractant peut rendre l’évolution apparente trompeuse. Un résultat non mesuré demeure inconnu : il n’est pas remplacé par zéro. Le cours apprend les questions à poser, sans donner de protocole de prélèvement universel.",
    nodes: [["Représentativité", "À quelle zone répond l’échantillon ?"], ["Historique", "Quels apports et événements ?"], ["Projet", "Quel objectif et quelles contraintes ?"]],
    activity: activity("analysis", 2, "dossier", "Compléter le dossier A/B", "Les deux analyses fictives existent, mais le projet, l’historique des apports et l’état des racines ne sont pas renseignés.", "Quel complément est prioritaire pour interpréter une difficulté de nutrition ?", [["a", "La couleur préférée de l’étiquette commerciale.", false, "Elle ne décrit pas les mécanismes du sol ou de la plante."], ["b", "Historique, racines, humidité, objectif et analyses compatibles avec la question.", true, "Ces éléments peuvent départager les mécanismes et préciser le besoin réel."], ["c", "Une valeur absente remplacée par zéro pour terminer le calcul.", false, "Une donnée non mesurée ne devient pas une mesure nulle."]], [["a", "Le résultat analytique doit être relié au fonctionnement et au périmètre du dossier.", true, "Le contexte donne sa portée au nombre."], ["b", "L’analyse dispense d’observer les plantes et le profil.", false, "Les observations apportent des informations différentes."]], "Compléter ce qui peut modifier la conclusion, sans inventer les inconnues.", ["methods", "assessment", "nutrition", "rhizosphere"]), terms: ["representativeness", "history", "monitoring", "uncertainty"], next: "Comment ramener ce raisonnement au chanvre autorisé ?", keys: ["methods", "assessment", "nutrition", "rhizosphere"] }),
];

const hempLessons = [
  lesson("hemp", 1, { title: "Un projet de chanvre, un contexte", question: "Un nom de variété donne-t-il tous ses besoins ?", objective: "Relier débouché, environnement et fournitures sans recette universelle.",
    essential: ["Les situations pratiques du parcours concernent uniquement du chanvre autorisé. Un projet fibre, graine ou mixte n’a pas exactement les mêmes objectifs ni les mêmes critères de produit. Le sol, l’environnement, le matériel végétal, l’historique et les fournitures déjà présentes doivent être considérés. Besoin biologique, quantité exportée par une récolte et apport éventuel ne sont pas trois nombres identiques.", "La fiche réelle de Carmagnola, HH2026-045, raconte une origine piémontaise et des usages de semences, fibres et cordages. Ce récit renseigne une histoire ; il ne donne pas une analyse du sol ni un besoin universel. La carte reste consultable sans possession. Son nom ne prouve ni adaptation locale ni autorisation actuelle d’un lot."],
    example: "Deux projets fictifs utilisent la même référence historique, l’un pour la fibre, l’autre pour la graine. Le joueur demande leurs contextes et objectifs au lieu de copier un programme unique.",
    deeper: "Le guide français 2026 relie la conduite à des débouchés et au contexte agronomique. On en retient la nécessité de raisonner les fournitures, sans recopier ses doses ou calendriers. Les éléments contenus dans les tissus exportés ne résument pas tous les flux du système : résidus, racines et pertes comptent selon le périmètre. Une fiche variétale ou un slogan chanvre peu exigeant ne remplace donc pas l’observation et l’analyse du projet concret.",
    nodes: [["Débouché", "Fibre, graine ou objectif mixte"], ["Milieu", "Sol, racines, environnement et historique"], ["Preuves", "Données pertinentes pour le projet"]],
    activity: activity("hemp", 1, "documents", "La carte n’est pas une analyse", "Dans un projet fictif, la fiche réelle Carmagnola est utilisée pour justifier un besoin nutritionnel identique sur tous les sols.", "Quelle lecture respecte la fiche ?", [["a", "L’ancienneté établit un besoin identique partout.", false, "Une histoire de variété n’est pas une étude de besoins dans tous les milieux."], ["b", "Le nom prouve l’autorisation de tout lot actuel.", false, "Le statut d’un lot et du projet se vérifie séparément."], ["c", "La fiche documente une histoire ; le besoin du projet reste à évaluer.", true, "Le contenu historique n’est pas transformé en prescription agronomique."]], [["a", "Le niveau et l’objet de la preuve doivent correspondre à l’affirmation.", true, "Une origine et un usage historique ne décrivent pas la parcelle actuelle."], ["b", "Un débouché fibre et un débouché graine sont toujours interchangeables.", false, "Les objectifs et les matières recherchées diffèrent."]], "Une référence historique ouvre des questions, elle ne fixe pas une recette.", ["buddy", "hemp"]), terms: ["outlet", "export", "supply"], next: "Comment conclure et vérifier une décision proportionnée ?", keys: ["buddy", "hemp", "nutrition"], buddyCodes: ["HH2026-045"] }),
  lesson("hemp", 2, { title: "Observer, décider, vérifier", question: "Comment agir sans transformer l’incertitude en certitude ?", objective: "Construire une décision proportionnée et un suivi mesurable.",
    essential: ["La démarche commence par observer : plante, profil, racines et répartition. On analyse ensuite ce qui répond à la question, avec des méthodes et un périmètre explicites. Comprendre les limites évite de confondre stock, disponibilité, absorption et résultat. Plusieurs causes peuvent rester compatibles ; ne pas conclure trop tôt est parfois la réponse la plus solide.", "Une action proportionnée répond à un objectif et à des preuves, dans un cadre vérifié. Le résultat est ensuite mesuré avec un critère défini et une comparaison pertinente. L’absence d’intervention peut aussi être justifiée en attendant une information décisive. Le suivi conserve les changements concomitants : une amélioration après une action ne prouve pas à elle seule une causalité exclusive."],
    example: "Dans un cas fictif, les racines sont peu documentées et deux méthodes analytiques diffèrent. La décision consiste d’abord à compléter le dossier, puis à choisir un suivi comparable plutôt qu’à multiplier les apports.",
    deeper: "Un indicateur utile dépend de l’objectif : état racinaire, propriété du sol ou critère de produit ne se remplacent pas. Le suivi doit préciser ce qui est attendu, ce qui est réellement mesuré et ce qui demeure inconnu. Les slogans sol vivant, tout organique ou tout minéral ne constituent pas des critères de réussite. Une conclusion solide peut rapporter une amélioration limitée, une absence d’effet ou un résultat encore incertain, sans sélectionner seulement les observations favorables.",
    nodes: [["Observer et analyser", "Données liées à la question"], ["Comprendre et choisir", "Limites, objectif et proportionnalité"], ["Mesurer à nouveau", "Résultat, comparateur et autres changements"]],
    activity: activity("hemp", 2, "order", "Construire la décision", "Un dossier fictif comporte des symptômes ambigus et des mesures incomplètes ; aucune urgence précise n’est établie.", "Quel enchaînement est cohérent ?", [["a", "Observer → analyser → comprendre les limites → choisir une action proportionnée → mesurer le résultat.", true, "Chaque étape prépare la suivante et le suivi peut rouvrir l’enquête."], ["b", "Choisir un produit → attribuer ensuite tous les symptômes à ce qu’il corrige.", false, "Cette démarche recherche une justification après la décision."], ["c", "Augmenter tous les apports → considérer toute amélioration comme une preuve exclusive.", false, "Elle ignore les causes possibles, les excès et les autres changements."]], [["a", "La décision et sa vérification doivent correspondre à des preuves et à un objectif explicites.", true, "L’incertitude est gérée, pas dissimulée."], ["b", "Une action suivie d’un changement prouve toujours son rôle unique.", false, "La chronologie seule n’exclut pas d’autres causes."]], "Une décision rigoureuse reste vérifiable et révisable.", ["assessment", "methods", "hemp", "inoculation"]), terms: ["proportionality", "monitoring", "comparator", "uncertainty"], next: "Quelle notion du dossier aimeriez-vous vérifier à nouveau ?", keys: ["assessment", "methods", "hemp", "inoculation"] }),
];

function chapter(id: string, number: number, title: string, introduction: string, context: HistoryChapter["context"], lessons: readonly HistoryLesson[], checkpoint: HistoryActivity): HistoryChapter { return { id, number, title, introduction, context, lessons, checkpoint }; }
